frm.example:
// 1. Set a single field value:
frm.set_value("posting_date", frappe.datetime.nowdate());

// 2. Set multiple fields simultaneously with an object:
frm.set_value({
    status: "Approved",
    approved_by: frappe.session.user,
    approval_date: frappe.datetime.nowdate()
});

// 1. Make field mandatory:
frm.set_df_property("tax_id", "reqd", 1);

// 2. Hide a field conditionally:
frm.set_df_property("discount_percentage", "hidden", frm.doc.total < 1000);

// 3. Modify options in a Select field:
frm.set_df_property("priority", "options", ["Low", "Medium", "High", "Urgent"]);

frm.add_custom_button(__("Create Invoice"), function() {
    frappe.model.open_mapped_doc({
        method: "erpnext.selling.doctype.sales_order.sales_order.make_sales_invoice",
        frm: cur_frm
    });
}, __("Create"));

if (frm.is_dirty()) {
    frappe.show_alert({ message: __("You have unsaved changes!"), indicator: "orange" });
}

let row = frm.add_child("items", {
    item_code: "ITEM-001",
    qty: 5,
    rate: 100
});
frm.refresh_field("items");

const itemsField = frm.get_field("items");
const grid = itemsField.grid;
grid.refresh();

